import{_ as t,o as s,c as e,a4 as i}from"./chunks/framework.BRzJ4ijD.js";const g=JSON.parse('{"title":"DHCP / ARP / NDP","description":"","frontmatter":{},"headers":[],"relativePath":"networking/ip/arp-dhcp.md","filePath":"networking/ip/arp-dhcp.md","lastUpdated":1788475713000}'),n={name:"networking/ip/arp-dhcp.md"};function l(r,a,p,d,o,h){return s(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="dhcp-arp-ndp" tabindex="-1">DHCP / ARP / NDP <a class="header-anchor" href="#dhcp-arp-ndp" aria-label="Permalink to &quot;DHCP / ARP / NDP&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>IP 地址不是绑定网卡的物理属性；地址解析、地址分配靠 ARP（IPv4）和 NDP（IPv6）+ DHCPv4 / DHCPv6/SLAAC 完成。这一节讲协议细节、安全陷阱、企业网络实践。</p><h2 id="arp-概览" tabindex="-1">ARP 概览 <a class="header-anchor" href="#arp-概览" aria-label="Permalink to &quot;ARP 概览&quot;">​</a></h2><p>ARP 不是 L2 协议也不是 L3 协议；它是&quot;用 IP 解 MAC&quot;的桥接：</p><ol><li>主机 A 想发到 192.0.2.5</li><li>查 ARP cache，没命中 -&gt; 发广播 <code>Who has 192.0.2.5?</code> (EtherType 0x0806)</li><li>主机 B 应单播 <code>192.0.2.5 is at 11:22:33:44:55:66</code></li><li>A 在 cache 写入 IP→MAC，设 15-30 min TTL</li><li>之后 A 直接封装 Ethernet 帧发送</li></ol><h3 id="arp-packet-结构" tabindex="-1">ARP packet 结构 <a class="header-anchor" href="#arp-packet-结构" aria-label="Permalink to &quot;ARP packet 结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| HW type (16) | Proto type (16) | HW len (8) | Proto len (8) | Op (16) |</span></span>
<span class="line"><span>| Sender hardware addr (HWlen)  | Sender protocol addr (Plen)            |</span></span>
<span class="line"><span>| Target hardware addr (HWlen)  | Target protocol addr (Plen)            |</span></span></code></pre></div><p>类型 1=Ethernet, 2=IPv4, op 1=request, 2=reply. ARP 包 42-60 字节（不够 64 需要链路层 padding）。</p><h3 id="gratuitous-arp-acd" tabindex="-1">Gratuitous ARP / ACD <a class="header-anchor" href="#gratuitous-arp-acd" aria-label="Permalink to &quot;Gratuitous ARP / ACD&quot;">​</a></h3><p>主机开机或 IP 改变后发一个 ARP 广播宣告 <code>my IP is at my MAC</code>，未请求的广播。用于：</p><ul><li>防止冲突（ACD，Address Conflict Detection）</li><li>高可用切换：主备 VIP 漂移后让交换机刷新 MAC 表（这点 Linux 的 keepalived 默认会发）</li></ul><hr><h2 id="dhcpv4-流程" tabindex="-1">DHCPv4 流程 <a class="header-anchor" href="#dhcpv4-流程" aria-label="Permalink to &quot;DHCPv4 流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>client -&gt; DISCOVER (broadcast UDP 67)</span></span>
<span class="line"><span>servers -&gt; OFFER (broadcast/unicast, UDP 68)</span></span>
<span class="line"><span>client -&gt; REQUEST   (挑一个，含 server id)</span></span>
<span class="line"><span>server -&gt; ACK       (含 lease_time, options)</span></span></code></pre></div><p>DHCP Options 丰富：</p><table tabindex="0"><thead><tr><th>CODE</th><th>Option</th><th>备注</th></tr></thead><tbody><tr><td>1</td><td>Subnet Mask</td><td></td></tr><tr><td>3</td><td>Router (default gateway)</td><td></td></tr><tr><td>6</td><td>DNS Servers</td><td></td></tr><tr><td>12</td><td>Hostname</td><td></td></tr><tr><td>51</td><td>Lease Time</td><td></td></tr><tr><td>53</td><td>DHCP Message Type</td><td>必备</td></tr><tr><td>54</td><td>DHCP Server Identifier</td><td></td></tr><tr><td>82</td><td>Relay Agent Information</td><td>DHCP Snooping 用</td></tr><tr><td>119</td><td>Domain Search List</td><td></td></tr></tbody></table><h3 id="lease-续约" tabindex="-1">Lease 续约 <a class="header-anchor" href="#lease-续约" aria-label="Permalink to &quot;Lease 续约&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T1 = 0.5 * lease_time        -&gt; 看门狗，找原 server 续</span></span>
<span class="line"><span>T2 = 0.875 * lease_time       -&gt; 原 server 失联，找任何 server</span></span>
<span class="line"><span>lease_time 到期              -&gt; 必须放掉 IP</span></span></code></pre></div><p>默认租约 24 小时；本机查看：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/dhcp/dhclient.leases</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Debian/Ubuntu</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/db/dhcpd_leases</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nmcli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> IP4.ADDRESS</span></span></code></pre></div><h3 id="dhcp-relay-rfc-3046-option-82" tabindex="-1">DHCP Relay（RFC 3046 Option 82） <a class="header-anchor" href="#dhcp-relay-rfc-3046-option-82" aria-label="Permalink to &quot;DHCP Relay（RFC 3046 Option 82）&quot;">​</a></h3><p>L3 网段到 DHCP server 跨网段时，relay agent 把 client 广播转单播发到 server：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>client ----broadcast----&gt; relay</span></span>
<span class="line"><span>  relay -unicast to DHCP- with Option 82 (Agent Circuit ID + Remote ID)</span></span>
<span class="line"><span>        &lt;- response from DHCP with Option 82</span></span>
<span class="line"><span>relay ----broadcast-----&gt; client</span></span></code></pre></div><p><strong>Option 82</strong> 是企业网大规模集中 DHCP 的基础：在大楼 L2 接入交换机上启 DHCP Snooping，所有 DHCP 包按端口抓包 + 在 Option 82 里塞入口标识，集中 DHCP server 能据此分出每个接入端口实际在公司哪个楼层。<strong>Cable MSO 用 DHCP Option 82 给家里 CM (cable modem) 分 IP</strong>。</p><hr><h2 id="arp-安全陷阱" tabindex="-1">ARP 安全陷阱 <a class="header-anchor" href="#arp-安全陷阱" aria-label="Permalink to &quot;ARP 安全陷阱&quot;">​</a></h2><h3 id="arp-欺骗-arp-spoofing" tabindex="-1">ARP 欺骗（ARP Spoofing） <a class="header-anchor" href="#arp-欺骗-arp-spoofing" aria-label="Permalink to &quot;ARP 欺骗（ARP Spoofing）&quot;">​</a></h3><p>LAN 上任何主机可发伪造的 ARP Reply：&quot;192.0.2.1 is at attacker_mac&quot;，邻居 ARP cache 被污染，所有去 192.0.2.1 的帧到达攻击者。Linux 工具：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># arpspoof from dsniff 套件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arpspoof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.0.2.10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.0.2.1</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 现在所有 192.0.2.10 -&gt; 192.0.2.1 的包都到攻击机</span></span></code></pre></div><p>防御：</p><ul><li>交换机 <strong>Dynamic ARP Inspection (DAI)</strong>，只允许 DHCP snooping 表里记录的 IP/MAC 映射发 ARP Reply</li><li>主机静态 ARP——但移动场景难维护</li><li>802.1X + MACsec 加密链路层数据 → 二层攻击者看不到加密内容</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>MACsec</strong> (IEEE 802.1AE) 在 L2 做 AES-GCM 加密 → 即使接入了恶意设备，所有跨 link 的帧都是密文。数据中心管理网 / 5G 时代电网 BN（backhaul network）常用。</p></div><h3 id="proxy-arp" tabindex="-1">Proxy ARP <a class="header-anchor" href="#proxy-arp" aria-label="Permalink to &quot;Proxy ARP&quot;">​</a></h3><p>某些路由器（如 K8s Calico、docker0 bridge）开启 optional &quot;代理 ARP&quot;：对其它子网里 IP 也能应 ARP（拿自己的 MAC 当网关）。</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>配错会让 client 觉得到外网直连，反而漏了路由器的存在。K8s Calico 用 BGP + Proxy ARP 解决 CNI 子网跨节点访问，但要确保 iptables/IPVS 规则也跟得上，否则冲突时容易丢包。</p></div><hr><h2 id="ipv6-ndp-取代-arp" tabindex="-1">IPv6 NDP（取代 ARP） <a class="header-anchor" href="#ipv6-ndp-取代-arp" aria-label="Permalink to &quot;IPv6 NDP（取代 ARP）&quot;">​</a></h2><p>NDP 用 ICMPv6 over IPv6 link local (<code>fe80::/10</code>)：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>host sends NS to solicited-node multicast ff02::1:ffXX:XXXX</span></span>
<span class="line"><span>target responds NA from its link-local src</span></span>
<span class="line"><span>host updates Neighbor Cache</span></span></code></pre></div><p>solicited-node 组播用最后 24 bit MAC 派生地址，<strong>比纯广播负载低很多</strong>：8 台主机分别对应 8 个 solicited-node 多播地址，互不打扰。</p><h3 id="dad-duplicate-address-detection" tabindex="-1">DAD（Duplicate Address Detection） <a class="header-anchor" href="#dad-duplicate-address-detection" aria-label="Permalink to &quot;DAD（Duplicate Address Detection）&quot;">​</a></h3><p>加新地址前发 NS 询问此地址在不在；2s 没人回 -&gt; 接管。<code>Tentative</code> 状态保持期约 1s。</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>在 WiFi 漫游 / 中断场景下，DAD 会延迟到几秒，几秒内服务断。<strong>优化1</strong>：RFC 7527 Optimistic DAD 让 client 紧急时使用 tentative 地址。<strong>优化2</strong>：RFC 4429 SEcure Neighbor Discovery (SEND) 用 RSA 地址防伪。</p></div><h3 id="路由器发现-slaac" tabindex="-1">路由器发现 (SLAAC) <a class="header-anchor" href="#路由器发现-slaac" aria-label="Permalink to &quot;路由器发现 (SLAAC)&quot;">​</a></h3><p>参见 <a href="./ipv6">IPv4/IPv6/ICMP</a> 那节。RA 报文 RA flags 控制：</p><ul><li><code>A</code> flag → 用 SLAAC</li><li><code>M</code> flag → 用 DHCPv6</li><li><code>O</code> flag → 用 stateless DHCPv6（只拿 DNS）</li></ul><h3 id="ndp-攻击" tabindex="-1">NDP 攻击 <a class="header-anchor" href="#ndp-攻击" aria-label="Permalink to &quot;NDP 攻击&quot;">​</a></h3><p>NA 欺私、伪造 RS/RA -&gt; 整网关路由都被劫持。 <strong>RA Guard</strong> 在交换机丢弃 client 端口的 RA。Cisco/Aruba 等大厂商接入交换机必启。</p><hr><h2 id="dhcpv6-vs-slaac" tabindex="-1">DHCPv6 vs SLAAC <a class="header-anchor" href="#dhcpv6-vs-slaac" aria-label="Permalink to &quot;DHCPv6 vs SLAAC&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>SLAAC</th><th>DHCPv6 stateful</th></tr></thead><tbody><tr><td>配置朴实</td><td>自动</td><td>需部署 DHCP server</td></tr><tr><td>DNS NTP 配置</td><td>通过 RA RDNSS option 或 stateless DHCPv6</td><td>通过 options</td></tr><tr><td>日志可追溯</td><td>难</td><td>可定位 IP 签发历史</td></tr><tr><td>IPv4 + IPv6 共存</td><td>自动 SLAAC</td><td>需编排</td></tr><tr><td>临时地址（Privacy）</td><td>与 SLAAC 配合佳</td><td>DHCPv6 不能签 Privacy 地址</td></tr></tbody></table><p>企业网络部署最佳实践：<strong>SLAAC + stateless DHCPv6 (拿 DNS + sip战)</strong>。运营商通常用 SLAAC + DHCPv6-PD (Prefix Delegation)，给家里下发 /56 或 /60 一段继续分给客户家中各个 subnet。</p><hr><h2 id="真实生产事故" tabindex="-1">真实生产事故 <a class="header-anchor" href="#真实生产事故" aria-label="Permalink to &quot;真实生产事故&quot;">​</a></h2><ol><li><strong>CERNET 2016 一个 EchoStorm 攻击</strong>: 一个学生的笔记本被植入恶意软件，发 Gratuitous ARP 把自己宣告为网关 → 所有学生断网 → 被 ARP table 老化迅速传播，校园网 2000 终端中毒样式 flood。<strong>修复</strong>：所有接入交换机启 DAI + DHCP Snooping + 802.1X。<strong>教训</strong>：任何用户接入网关必须有二层 ARP 防御。</li><li><strong>AWS managed DHCP leaked KV 2017</strong>：Option 82 在某些 region 填错接口 ID，明明 Instance 在 us-east-1d，Option 82 显示 us-east-1b → 客户跨 AZ 链路计费正确性 ID 混乱。<strong>修复</strong>：AWS 后台重建所有 Option 82 + DHCP 流水。<strong>教训</strong>：只要 Option 82 进入业务关键路径，必须有独立审计。</li><li><strong>CDN 2018 RA Attack</strong>: 某 CDN POP 在客户服务器被 over-permissive 配置允许 RA → 网络被劫，部分客户失败。<strong>修复</strong>：所有客户端 → RA Guard（接入交换机端口规则）+ Ban 来路异常的 RA。<strong>教训</strong>：IPv6 安全模型与 IPv4 不同，但是迟 IPv6 部署反而激发了安全性提出更严。</li></ol><hr><h2 id="这一章带走的东西" tabindex="-1">这一章带走的东西 <a class="header-anchor" href="#这一章带走的东西" aria-label="Permalink to &quot;这一章带走的东西&quot;">​</a></h2><ol><li>ARP 是 ~25 µs 的 LAN 互信，但 MACsec 是新加 L2 防御</li><li>DHCP Option 82 是跨网段 DHCP 关键 + 企业网 Cable MSO 大量用</li><li>NDP 比 ARP 多了 DAD + 组播 + 多选项，且 RA/RS 取代广播减少了 LAN 单包负载</li><li>DAI + RA Guard 是企业级 L2 安全面，与 802.1X 配合构成纵深防御</li><li>部署 DHCPv6 vs SLAAC 时视场景选；类 IPv4 的运维ásiongan 仍有&quot;日志可追溯&quot;价值</li></ol><p>下一节 → <a href="./bgp-ospf">BGP / OSPF 路由</a></p>`,60)])])}const P=t(n,[["render",l]]);export{g as __pageData,P as default};
